// Heartbeat corner cases for tests/hb_cases.h, answered by the Swift reference itself:
// empty strings, Thai at the 63-byte and 20-character limits, and the scripts whose
// characters are several code points (Devanagari conjuncts, Hangul jamo, ZWJ, prepend marks).
//   T=$(mktemp -d); cp tools/hb_cases.swift $T/main.swift
//   swiftc -O ../../desk-pet-mac/Sources/PetProtocol/Heartbeat.swift $T/main.swift -o $T/g
//   (echo '/* generated by tools/hb_cases.swift from Heartbeat.swift: do not edit */'; $T/g) > tests/hb_cases.h
import Foundation
import PetProtocol
func c(_ s: String) -> String {   // as a C string literal, bytes >= 0x80 and controls in octal
  var o = "\""
  for b in s.utf8 {
    if b == 0x22 { o += "\\\"" } else if b == 0x5C { o += "\\\\" } else if b < 0x20 || b >= 0x7F { o += String(format: "\\%03o", b) } else { o += String(UnicodeScalar(b)) }
  }
  return o + "\""
}
let cases: [(String, String, String?)] = [
  ("empty_who", "", ""),
  ("thai_21", String(repeating: "ก", count: 22), nil),
  ("thai_marks", String(repeating: "ก่", count: 11), String(repeating: "กี่", count: 21)),
  ("thai_sara_am", String(repeating: "น้ำ", count: 8), "น้ำ" + String(repeating: "ใจ", count: 12)),
  ("devanagari", String(repeating: "क्षि", count: 6), String(repeating: "क्षि", count: 21)),
  ("hangul_jamo", String(repeating: "\u{1100}\u{1161}\u{11A8}", count: 8), String(repeating: "각\u{11A8}", count: 22)),
  ("zwj_letters", String(repeating: "a\u{200D}b", count: 20), String(repeating: "a\u{200D}b", count: 11)),
  ("family", String(repeating: "👨‍👩‍👧", count: 4), String(repeating: "🏴󠁧󠁢󠁳󠁣󠁴󠁿", count: 21)),
  ("prepend", String(repeating: "\u{0600}1", count: 30), String(repeating: "\u{0600}1", count: 21)),
  ("zwsp_mark", String(repeating: "\u{200B}\u{0301}", count: 12), String(repeating: "\u{200B}\u{0301}", count: 11)),
  ("escapes", "\"\\\n\t\r\u{1}\u{1f}\u{7f}\u{85}\u{2028}/", "\"q\"\\"),
]
for (name, msg, who) in cases {
  let hb = Heartbeat(total: 1, running: 0, waiting: 0, msg: msg, epoch: 2, tzoff: 3, who: who)
  print("    { \"\(name)\", \(c(msg)), \(who.map(c) ?? "NULL"),\n      \(c(String(decoding: hb.jsonLine(), as: UTF8.self))) },")
}
